from .base import EMSSInterface
from ..utilities.pmconverter import PMConverter
from ..utilities.rtpmconverter import RTPMConverter, NoRtpmIntervalCollected
from ..utilities.EmssFileLogger import get_robot_output_dir
import time
import re
import os
import shutil
import datetime


class PMManager(EMSSInterface):
    """
    EMSsim keywords related to pm_counters
    """

    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'  # 'TEST CASE' 'GLOBAL'

    def __init__(self):
        super(PMManager, self).__init__()

    def _is_rtpm_interval_used(self):
        return True if self.rtpm_interval['start'] is not None and self.rtpm_interval['stop'] is not None else False

    def rtpm_activate(self, retry_limit=3, retry_sleep=300, enb_id=None, bts_id=None, alias=None):
        """
        Activates RTPM.

        :param retry_limit: Number of retries if failed (default=3)
        :param retry_sleep: Time in seconds between retries (default=300)
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        """
        retry_limit = self._opt_int(retry_limit)
        retry_sleep = self._opt_int(retry_sleep)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self.enb_configuration_should_be_discovered(bts_id=bts_id, alias=alias)
        cmd = self._get_emssim().cmd_rtpm_activate()
        command_succeeded = self._run_repeat_command(cmd, retry_limit=retry_limit, retry_sleep=retry_sleep)
        self._assert(command_succeeded, "Activation of RTPM failed")
        self.rtpm_interval['rtpm_activate'] = datetime.datetime.now()

    def rtpm_clean(self, enb_id=None, bts_id=None, alias=None):
        """
        Cleans RTPM files.

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        cmd = self._get_emssim().cmd_rtpm_clean()
        self._assert(cmd.run(), "Could not clean RTPM files")
        self.rtpm_interval = {'start': None,
                              'stop': None}

    def rtpm_deactivate(self, enb_id=None, bts_id=None, alias=None):
        """
        Deactivates RTPM.

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self.enb_configuration_should_be_discovered()
        cmd = self._get_emssim().cmd_rtpm_deactivate()
        command_succeeded = self._run_repeat_command(cmd)
        self._assert(command_succeeded, "Deactivation of RTPM failed")
        self.rtpm_interval['rtpm_activate'] = None

    def get_value_of_counter(self, object_name, counter_id, enb_id=None, bts_id=None, alias=None):
        """
        Returns value of the given object's counter.

        :param object_name: Name of the object, e.g. DN:NE-LNBTS-88/FTM-1/ETHLK-0-1
        :param counter_id: counter ID, e.g. M51123C0
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :return: counter value
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        output = self._get_output_of_parsed_pm_file(counter_id)
        try:
            PMC = PMConverter(output["measurement_table"])
            return PMC.get_counter_value(object_name, counter_id)
        except KeyError:
            print("ERROR: Counter not exists: %s" % counter_id)
            raise

    def verify_value_of_counter(self, object_name, counter_id, value, enb_id=None, bts_id=None, alias=None):
        """
        Verify value of the given object's counter.

        :param object_name: Name of object, e.g. LNCEL-1
        :param counter_id: Counter ID., e.g. M8006C256
        :param value: Expected counter value - numeric or list [min,max]
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +-------------------------+---------------------+----------------------+-------------+
        |                        Example                                                     |
        +=========================+=====================+======================+=============+
        | Verify value of counter | object_name=LNCEL-1 | counter_id=M8006C262 | value=2     |
        +-------------------------+---------------------+----------------------+-------------+
        | Verify value of counter | object_name=LNCEL-1 | counter_id=M8006C262 | value=[1,3] |
        +-------------------------+---------------------+----------------------+-------------+
        """
        value = self._opt_int_or_list(value)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        counter_value = int(self.get_value_of_counter(object_name, counter_id, bts_id=bts_id, alias=alias))
        self._assert(self._check_value(counter_value, value),
                     "Counter: {} value: {} is not as expected value: {}.".format(counter_id, counter_value, value))

    def get_value_of_rtpm(self, object_name, counter_id, enb_id=None, bts_id=None, alias=None):
        """
        Returns value of the given object's counter.

        :param object_name: Name of the object, e.g. DN:NE-LNBTS-88/FTM-1/ETHLK-0-1
        :param counter_id: counter ID, e.g. M51123C0
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :return: sum of all received RTPM values for counter
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        output = self._get_output_of_parsed_rtpm_file(counter_id)
        try:
            rtpm_data = output['rtpm_data'] if 'rtpm_data' in output else None
            RTPM = RTPMConverter(output["measurement_table"], rtpm_data=rtpm_data)
            return RTPM.get_counter_value(object_name, counter_id)
        except KeyError:
            print("ERROR: Counter not exists: %s" % counter_id)
            self._copy_rtpm_files()
            raise

    def get_all_values_of_rtpm(self, counter_id, full_dn=False, enb_id=None, bts_id=None, alias=None):
        """
        Return all values of the given counter ID.

        :param counter_id: counter ID, e.g. M51123C0
        :param full_dn: Report full object DN instead of simplified class and ID (default=False)
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :return: table of all received RTPM values for counter with object name pattern
        """
        full_dn = self._opt_bool(full_dn)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        output = self._get_output_of_parsed_rtpm_file(counter_id)
        try:
            rtpm_data = output['rtpm_data'] if 'rtpm_data' in output else None
            RTPM = RTPMConverter(output["measurement_table"], rtpm_data=rtpm_data)
            ret = RTPM.get_all_counter_values(counter_id)
            if full_dn:
                return ret
            new_ret = {}
            for dn in ret.keys():
                srch = re.search(r'([^/]+)$', dn)
                if srch:
                    moi = srch.group(1)
                    if moi in new_ret:
                        raise Exception(f"Duplicate key {moi} for DN={dn}. Use option: full_dn=True.")
                    new_ret[srch.group(1)] = ret[dn]
                else:
                    new_ret[dn] = ret[dn]
            return new_ret
        except KeyError:
            print("ERROR: Counter not exists: %s" % counter_id)
            self._copy_rtpm_files()
            raise

    def get_value_of_rtpm_if_exists(self, object_name, counter_id, enb_id=None, bts_id=None, alias=None):
        """
        Return value is a sum off the all existing rtpm counter values. Initial value is 0.

        :param object_name: Name of the object, e.g. DN:NE-LNBTS-88/FTM-1/ETHLK-0-1
        :param counter_id: counter ID, e.g. M51123C0
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :return: sum of all received RTPM values for counter
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        if self._is_rtpm_interval_used() is True:
            timestamps = (self.rtpm_interval['start'], self.rtpm_interval['stop'])
        else:
            timestamps = None
        ret = 0
        output = self._get_output_of_parsed_rtpm_file(counter_id)
        try:
            rtpm_data = output['rtpm_data'] if 'rtpm_data' in output else None
            RTPM = RTPMConverter(output["measurement_table"], skip_not_valid_counters=1, rtpm_data=rtpm_data, interval_timestamps=timestamps)
            ret = RTPM.get_counter_value(object_name, counter_id)
        except KeyError:
            print("Counter not exists: %s" % counter_id)
            self._copy_rtpm_files()
        return ret

    def get_time_of_latest_counter_update(self, object_name, counter_id, enb_id=None, bts_id=None, alias=None):
        """
        Returns last counter update time.

        :param object_name: Name of object, e.g. DN:NE-LNBTS-88/FTM-1/ETHLK-0-1
        :param counter_id: counter ID, e.g. M51123C0
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        output = self._get_output_of_parsed_pm_file(counter_id)
        PMC = PMConverter(output["measurement_table"])
        return PMC.get_counter_update_time(object_name, counter_id)

    def _get_output_of_parsed_pm_file(self, counter_id):
        filter = "-cfilter %s" % counter_id
        parse_pm_file_command = self._get_emssim().cmd_parse_pm_file()
        self._assert(parse_pm_file_command.run(filter), "Command parse_pm_file failed")
        return parse_pm_file_command.returned_data()

    def _get_output_of_parsed_rtpm_file(self, counter_id):
        counter_id = RTPMConverter.counter_id_int(counter_id)
        filter = "-cfilter %s" % counter_id
        parse_rtpm_file_command = self._get_emssim().cmd_rtpm_parse()
        self._assert(parse_rtpm_file_command.run(filter), "Command rtpm_parse failed")
        return parse_rtpm_file_command.returned_data()

    def get_time_to_next_pm_file_generation(self, enb_id=None, bts_id=None, alias=None):
        """
        Returns time to next pm file generation for auto_stats.

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +--------------------------------+-------------------------------------+
        |                             Example                                  |
        +================================+=====================================+
        |        ${next_run_time}=       | get_time_to_next_pm_file_generation |
        +--------------------------------+-------------------------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        auto_stats_command = self._get_emssim().cmd_auto_stats()
        self._assert(auto_stats_command.run(), "Command auto_stats failed")
        result_of_auto_stats_cmd = auto_stats_command.returned_data()
        return result_of_auto_stats_cmd["information"]["next_run_after"]

    def wait_for_clean_rtpm_interval(self, clean_rtpm_files=False, clean_before_wait=False, clean_after_wait=False,
                                     wait_threshold=2, timeout=300, enb_id=None, bts_id=None, alias=None):
        """
        Clean RTPM files if needed and wait in a loop until 2 new RTPM files appear.
        Number of RTPM files to wait for can be customized with wait_threshold option.
        Setting clean_rtpm_files to True has the same result as setting clean_before_wait and clean_after_wait to True.

        :param clean_rtpm_files: (bool, default=False) Clean collected RTPM files before and after waiting
        :param clean_before_wait: (bool, default=False) Clean collected RTPM files before waiting
        :param clean_after_wait: (bool, default=False) Clean collected RTPM files after waiting
        :param wait_threshold: (int, default=2) Number of RTPM files to wait for
        :param timeout: (int, default=300) Timeout in seconds to wait for number of RTPM files given in wait_threshold
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        """
        clean_rtpm_files = self._opt_bool(clean_rtpm_files)
        clean_before_wait = self._opt_bool(clean_before_wait)
        clean_after_wait = self._opt_bool(clean_after_wait)
        wait_threshold = self._opt_int(wait_threshold)
        timeout = self._opt_int(timeout)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        time_left = timeout
        time_step = 10
        initial_collected_files = None
        if clean_rtpm_files or clean_before_wait:
            self._get_emssim().cmd_rtpm_clean(start=True)
        while time_left > 0:
            status = self._get_emssim().cmd_rtpm_status()
            status.run()
            collected_files_num = int(status.returned_data()['collected_files'])
            if initial_collected_files is None:
                initial_collected_files = collected_files_num
            if collected_files_num >= initial_collected_files + wait_threshold:
                break
            else:
                time.sleep(time_step)
            time_left -= time_step
        else:
            self.run_emssim_command("ps", bts_id=bts_id, alias=alias)
            self._assert(False, "RTPM files did not appear before timeout")
        if clean_rtpm_files or clean_after_wait:
            self._get_emssim().cmd_rtpm_clean(start=True)

    def wait_for_rtpm_before_test(self, enb_id=None, bts_id=None, alias=None):
        """
        Clean RTPM files and wait for next two RTPM files.

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self.wait_for_clean_rtpm_interval(clean_rtpm_files=True, wait_threshold=2, timeout=300, bts_id=bts_id, alias=alias)

    def wait_for_rtpm_after_test(self, enb_id=None, bts_id=None, alias=None):
        """
        Wait for next two RTPM files.

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self.wait_for_clean_rtpm_interval(clean_rtpm_files=False, wait_threshold=2, timeout=240, bts_id=bts_id, alias=alias)

    def verify_that_rtpm_counter_value_is_equal_to(self, object_name, counter_id, value, check_if_exists=False,
                                                   enb_id=None, bts_id=None, alias=None):
        """
        Checks if counter value collected with RTPM is equal to expected value

        :param object_name: Name of object, e.g. LNCEL-1
        :param counter_id: Counter ID., e.g. M8006C256
        :param value: Expected counter value - numeric or list of [min,max]
        :param check_if_exists (bool): Check if a given counter exists and throw an error if not (default=False)
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +--------------------------------------------+---------------------+----------------------+-------------+
        |                                               Example                                                 |
        +============================================+=====================+======================+=============+
        | Verify that rtpm counter value is equal to | object_name=LNCEL-1 | counter_id=M8006C262 | value=2     |
        +--------------------------------------------+---------------------+----------------------+-------------+
        | Verify that rtpm counter value is equal to | object_name=LNCEL-1 | counter_id=M8006C262 | value=[1,3] |
        +--------------------------------------------+---------------------+----------------------+-------------+
        """
        value = self._opt_int_or_list(value)
        check_if_exists = self._opt_bool(check_if_exists)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        counter_value = None
        if check_if_exists:
            counter_value = int(self.get_value_of_rtpm(object_name=object_name, counter_id=counter_id, bts_id=bts_id, alias=alias))
        else:
            counter_value = int(self.get_value_of_rtpm_if_exists(object_name=object_name, counter_id=counter_id, bts_id=bts_id, alias=alias))
        self._assert(self._check_value(counter_value, value),
                     "Counter: {} value: {} is not as expected value: {}.".format(counter_id, counter_value, value))
        self.already_checked_rtpm_counters.append(str(counter_id))

    def wait_for_interval_and_verify_rtpm_counter_value_and_report_to_rp(self, object_name, counter_id, value, timeout=240,
                                                                         enb_id=None, bts_id=None, alias=None):
        """
        Method waits until interval Tx or range of intervals [Tx, Tx+1, Tx+2] are visible within rtpm and then verifies all counters against that
        interval data. Only values for Tx intervals are taken into account, whre Tx is matching timestamp moment when Start Rtpm Collection Interval
        and Stop Rtpm Collection Interval was used.
        :param object_name:
        :param counter_id: comma separated counters in case of many values
        :param value:   comma separated counters in case of many values
        :param timeout: default 240s, suggest not to change to lower value
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :return:
        """
        bts_id = self._opt_id(enb_id, bts_id)
        timeout = self._opt_int(timeout)
        counter_ids = [str(counter).strip() for counter in str(counter_id).strip().split(',')]
        values = [str(val).strip() for val in str(value).strip().split(',')]

        self = self._get_instance(bts_id, alias)

        if self._is_rtpm_interval_used() is True:
            while timeout > 0:
                wait_timer_start = time.time()
                self.wait_for_clean_rtpm_interval(clean_rtpm_files=False, wait_threshold=1, timeout=120, bts_id=bts_id, alias=alias)
                wait_timer_stop = int(time.time() - wait_timer_start)
                try:
                    for i, c_id in enumerate(counter_ids):
                        self.verify_rtpm_counter_value_and_report_to_rp(object_name=object_name, counter_id=c_id, value=values[i], bts_id=bts_id, alias=alias)
                    return
                except NoRtpmIntervalCollected:
                    timeout -= wait_timer_stop
            raise Exception('Did not collect interval data for timestamps :{}'.format(self.rtpm_interval))
        else:
            raise Exception('This method can be only used with intervals')

    def verify_rtpm_counter_value_and_report_to_rp(self, object_name, counter_id, value, enb_id=None, bts_id=None, alias=None):
        """
        Checks if counter value collected with RTPM is equal to expected value
        and add validation counter result to robot report.
        PM counter is not reported immediately. PM counter will be read by
        ute_reporting_portal script and then send to Reporting Portal.

        :param object_name: Name of object, e.g. LNCEL-1
        :param counter_id: Counter ID., e.g. M8006C256
        :param value: Expected counter value - numeric or list [min,max]
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +--------------------------------------------+---------------------+----------------------+-------------+
        |                                               Example                                                 |
        +============================================+=====================+======================+=============+
        | Verify rtpm counter value and report to RP | object_name=LNCEL-1 | counter_id=M8006C262 | value=2     |
        +--------------------------------------------+---------------------+----------------------+-------------+
        | Verify rtpm counter value and report to RP | object_name=LNCEL-1 | counter_id=M8006C262 | value=[1,3] |
        +--------------------------------------------+---------------------+----------------------+-------------+
        """
        value = self._opt_int_or_list(value)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        counter_value = int(self.get_value_of_rtpm_if_exists(object_name=object_name, counter_id=counter_id, bts_id=bts_id, alias=alias))

        if self._check_value(counter_value, value):
            self._report_pm_counter(counter_id, counter_value, 'Passed')
            self.already_checked_rtpm_counters.append(str(counter_id))
        else:
            self._report_pm_counter(counter_id, counter_value, 'Failed')
            self._assert(counter_value == value,
                         "Counter: {} value: {} is not as expected value: {}.".format(counter_id, counter_value, value))

    def verify_that_rtpm_counter_was_not_incremented(self, object_name, counter_id, enb_id=None, bts_id=None, alias=None):
        """
        Checks if counter value collected with RTPM is equal to zero

        :param object_name: Name of object, e.g. LNCEL-1l
        :param counter_id: Counter ID., e.g. M8006C256l
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +-----------------------------------------------+----------------------+------------------------+
        |                                       Example                                                 |
        +===============================================+======================+========================+
        | Verify that rtpm counter was not incremented  | object_name=LNCEL-1  |  counter_id=M8006C262  |
        +-----------------------------------------------+----------------------+------------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        counter_value = int(self.get_value_of_rtpm_if_exists(object_name=object_name, counter_id=counter_id, bts_id=bts_id, alias=alias))
        self._assert(counter_value == 0,
                     "Counter: {} was incremented by:: {}, but it should not be.".format(counter_id, counter_value))

    def verify_if_not_checked_rtpm_counters_are_not_incremented(self, object_name, counters_range, enb_id=None, bts_id=None, alias=None):
        """
        Verifies if range of counter is not incremented.
        It does not verify counters which were already checked with 'Verify that counter value is equal to' keyword

        :param object_name: Name of object, e.g. LNCEL-1
        :param counters_range: Counters range (from the same group), e.g. M8006C254-M8006C260
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +----------------------------------------------------------+-----------+-----------------------+
        |                                       Example                                                |
        +==========================================================+===========+=======================+
        | Verify if not checked rtpm counters are not incremented  |  LNCEL-1  |  M8006C254-M8006C268  |
        +----------------------------------------------------------+-----------+-----------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        range_start = int(re.findall(r'C(\d+)', counters_range.split('-')[0])[0])
        range_stop = int(re.findall(r'C(\d+)', counters_range.split('-')[1])[0])
        group_type = str(re.findall(r'(M\d+C)', counters_range.split('-')[0])[0])
        counters_list = []
        for x in range(range_start, range_stop + 1):
            counters_list.append(str(group_type) + str(x))
        for counter in counters_list:
            if counter not in self.already_checked_rtpm_counters:
                self.verify_that_rtpm_counter_was_not_incremented(object_name=object_name, counter_id=counter, bts_id=bts_id, alias=alias)

    def clear_already_checked_rtpm_counters_list(self, enb_id=None, bts_id=None, alias=None):
        """
        Clears already checked counters list

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self.already_checked_rtpm_counters = []

    def clear_rtpm_interval_values(self, enb_id=None, bts_id=None, alias=None):
        """
        Clears collected interval values in case non-interval way of rtpm collection to be used

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self.rtpm_interval['start'] = None
        self.rtpm_interval['stop'] = None

    def start_rtpm_collection_interval(self, wait_for_next_full_minute_interval=15, wait_for_next_minute_start=False, enb_id=None, bts_id=None, alias=None):
        """
        Sets starting point for rtpm interval. Wait if invoked just at the end of current interval. Additional, internal offset 1s added
        in case of starting at full minuted, e.g.1:01:00, interval will start 1:01:01
        :param wait_for_next_full_minute_interval:  default 15, it means when e.g. 15:45:46 is current time, keyword will wait 15s
        to start new interval
        :param wait_for_next_minute_start: If set to true, overrides wait_for_next_full_minute_interval timer and waits until new minute starts
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :return:
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        wait_for_next_full_minute_interval = int(wait_for_next_full_minute_interval)
        wait_for_next_minute_start = True if str(wait_for_next_minute_start).lower().strip() == 'true' else False
        offet_to_start_new_period = 1
        self.rtpm_interval['start'] = None
        self.rtpm_interval['stop'] = None
        timestamp = datetime.datetime.now()
        if 'rtpm_activate' in self.rtpm_interval and self.rtpm_interval['rtpm_activate'] is not None:
            if (timestamp - self.rtpm_interval['rtpm_activate']).total_seconds() <= 60:
                print('At least one period T gap must exist between activation of RTPM and checking first counters')
                wait_for_next_minute_start = True
                print("Setting wait_for_next_minute_start=True")
        second = timestamp.second
        time_left_in_current_period = 60 - int(second)
        if wait_for_next_minute_start is True or time_left_in_current_period <= wait_for_next_full_minute_interval:
            print('Waiting for {} seconds to start new 1 minute interval'.format(time_left_in_current_period + offet_to_start_new_period))
            time.sleep(time_left_in_current_period + offet_to_start_new_period)
            timestamp = datetime.datetime.now()
        self.rtpm_clean(bts_id=bts_id, alias=alias)
        self.rtpm_interval['start'] = timestamp

    def stop_rtpm_collection_interval(self, wait_for_next_full_minute_interval=5, enb_id=None, bts_id=None, alias=None):
        """
        When invoked, it ends current rtpm interval. Interval, can fit within one T-timestamp or many, e.g. [T1,T2,T3].
        :param wait_for_next_full_minute_interval: default 15s. If to close to end interval, waits to start a new one
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :return:
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        assert self.rtpm_interval['start'] is not None, "Use start rtpm collection interval method first"
        wait_for_next_full_minute_interval = int(wait_for_next_full_minute_interval)
        offet_to_start_new_period = 1
        timestamp = datetime.datetime.now()
        second = timestamp.second
        time_left_in_current_period = 60 - int(second)
        if time_left_in_current_period <= wait_for_next_full_minute_interval:
            time.sleep(time_left_in_current_period + offet_to_start_new_period)
        timestamp = datetime.datetime.now()
        self.rtpm_interval['stop'] = timestamp
        print('RTPM interval set to values: {} - {}'.format(self.rtpm_interval['start'].ctime(), self.rtpm_interval['stop'].ctime()))

    def wait_for_pm_file(self, timeout=None, enb_id=None, bts_id=None, alias=None, offset=1, period=15):
        """
        Wait for pm file.

        :param timeout: Maximum waiting time in seconds (default=(period+1)*60=16*60)
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :param offset: safety buffer in seconds to the end of interval (default=1)
        :param period: PM Stats collection period in minutes (default=15)

        +------------------+
        |       Examples   |
        +==================+
        | wait_for_pm_file |
        +------------------+
        """
        timeout = self._opt_int(timeout)
        bts_id = self._opt_id(enb_id, bts_id)
        offset = self._opt_int(offset)
        period = self._opt_int(period)
        if timeout is None:
            timeout = (period + 1) * 60

        self = self._get_instance(bts_id, alias)

        self._get_emssim().subscribe_events(event_type='file')
        pm_obj = None
        wait_time = 0
        time_to_end = ((period + 1) * 60) - (int(time.time()) % (period * 60))
        time_to_end = time_to_end - offset
        if time_to_end < 0:
            time_to_end = 1
        time.sleep(time_to_end)
        while wait_time < timeout:
            files = self._get_emssim().get_events(event_type='file')
            for fl in files:
                if ('ftype' in fl) and (fl['ftype'] == 'measurementFile'):
                    pm_obj = fl
            if pm_obj:
                print("PM FILE: %s" % str(pm_obj))
                break
            wait_time += 1
            time.sleep(1)
        else:
            self._get_emssim().unsubscribe_events(event_type='file')
            self._assert(False, "PM files did not appear before timeout")
        self._get_emssim().unsubscribe_events(event_type='file')

    def wait_for_clean_interval(self, offset=5, enb_id=None, bts_id=None, alias=None, period=15):
        """
        Wait for next pm interval.

        :param offset: safety buffer in seconds from start of interval (default=5)
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :param period: PM Stats collection period in minutes (default=15)

        +-------------------------+
        |       Examples          |
        +=========================+
        | wait_for_clean_interval |
        +-------------------------+
        """
        offset = self._opt_int(offset)
        period = self._opt_int(period)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        time_to_end = (period * 60) - (int(time.time()) % (period * 60)) + offset
        print("Waiting for clean PM interval for {} seconds.".format(time_to_end))
        time.sleep(time_to_end)

    def wait_for_next_interval(self, min_time=5, enb_id=None, bts_id=None, alias=None, min_time_sec=None, offset=5, period=15):
        """
        Wait for next pm interval if there are less than min_time minutes till the end of the current interval.

        :param min_time: minimum time in minutes between now and end of interval (default=5)
        :param min_time_sec: minimum time in seconds between now and end of interval, if present then overrides min_time
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :param offset: safety buffer in seconds from start of interval (default=5)
        :param period: PM Stats collection period in minutes (default=15)

        +------------------------+
        |       Examples         |
        +========================+
        | wait_for_next_interval |
        +------------------------+
        """
        min_time = self._opt_int(min_time)
        min_time_sec = self._opt_int(min_time_sec)
        offset = self._opt_int(offset)
        period = self._opt_int(period)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        if min_time_sec:
            min_time = min_time_sec
        else:
            min_time = min_time * 60

        time_to_end = (period * 60) - (int(time.time()) % (period * 60))
        if time_to_end <= min_time:
            print("Current PM stats interval will finish in {} seconds. Waiting for next interval.".format(time_to_end))
            time.sleep(time_to_end + offset)

    def _copy_rtpm_files(self):
        robot_log_dir = get_robot_output_dir()
        rtpm_files_dir = "/home/{}/UPLOADS/KEYSTATS/RTPM/".format(self.user)
        if os.path.exists(rtpm_files_dir) and robot_log_dir:
            try:
                outdir = robot_log_dir + '/emss/counters/'
                if os.path.exists(outdir):
                    shutil.rmtree(outdir, ignore_errors=True)
                shutil.copytree(rtpm_files_dir, outdir)
            except Exception as exc:
                print("Couldn't copy rtpm files: {}".format(str(exc)))

    def _check_value(self, counter_value, value):
        if (isinstance(value, list) and (int(value[0]) <= counter_value <= int(value[1]))) or (counter_value == value):
            return True
        return False

    def _report_pm_counter(self, counter_id, counter_value, result):
        try:
            from taf.sw.reporting_portal import reporting_portal
            reporting_portal().report_pm_counter(id=counter_id, value=counter_value, result=result)
        except Exception as exc:
            print("WARNING: ta_emss was not able to report pm counter to Reporting Portal: {}".format(exc))
